function skylineOutline(buildings: number[][]): number[][] {
  const xs = [...new Set(buildings.flatMap(b => [b[0], b[1]]))].sort((a, b) => a - b);
  const out: number[][] = [];
  let prev = 0;
  for (const x of xs) {
    let h = 0;
    for (const [l, r, bh] of buildings) if (l <= x && x < r) h = Math.max(h, bh);
    if (h !== prev) { out.push([x, h]); prev = h; }
  }
  return out;
}

