function skylineOutline(buildings) {
  const bs = [...buildings].sort((a, b) => a[0] - b[0]);
  const xs = [...new Set(bs.flatMap((b) => [b[0], b[1]]))].sort((a, b) => a - b);
  const h = [];
  const up = (i2) => {
    while (i2 > 0) {
      const p = i2 - 1 >> 1;
      if (h[p][0] >= h[i2][0]) break;
      [h[p], h[i2]] = [h[i2], h[p]];
      i2 = p;
    }
  };
  const down = (i2) => {
    for (; ; ) {
      let m = i2;
      const l = 2 * i2 + 1, r = l + 1;
      if (l < h.length && h[l][0] > h[m][0]) m = l;
      if (r < h.length && h[r][0] > h[m][0]) m = r;
      if (m === i2) return;
      [h[m], h[i2]] = [h[i2], h[m]];
      i2 = m;
    }
  };
  const pop = () => {
    const last = h.pop();
    if (h.length) {
      h[0] = last;
      down(0);
    }
  };
  const out = [];
  let i = 0, prev = 0;
  for (const x of xs) {
    while (i < bs.length && bs[i][0] === x) {
      h.push([bs[i][2], bs[i][1]]);
      up(h.length - 1);
      i++;
    }
    while (h.length && h[0][1] <= x) pop();
    const cur = h.length ? h[0][0] : 0;
    if (cur !== prev) {
      out.push([x, cur]);
      prev = cur;
    }
  }
  return out;
}
